"""Portable inspection panels; live review/reanalysis is enabled only on localhost."""
import html
import json
from pathlib import Path

from PIL import Image
from .reporting import encoded
from .review_ui import review_section
from .reasoning import sha


def render_reasoning(result,original,image,output):
    esc=lambda x:html.escape(str(x),quote=True)
    output=Path(output)
    run_id=output.name if output.parent.name=="reanalyses" else "baseline"
    evidence={e["id"]:e for e in result["evidence"]}
    views={v["id"]:v for v in result["views"]}
    images={vid:encoded(Image.open(output/v["file"]).convert("RGB")) for vid,v in views.items()}
    pictures=''.join(f'<figure id="picture-{esc(vid)}" class="picture" {"" if vid=="whole" else "hidden"}><img src="{images[vid]}" alt="{esc(vid)} · {esc(v["scale"])} view"><figcaption>{esc(vid)} · {esc(v["scale"])} · {v["size"][0]} × {v["size"][1]} pixels. No enlargement adds source detail.</figcaption></figure>' for vid,v in views.items())
    options=''.join(f'<option value="{esc(vid)}">{esc(vid)} · {esc(v["scale"])}</option>' for vid,v in views.items())
    cards=[]
    for explanation in result["explanations"]:
        cards.append(f'<h2 id="{esc(explanation["id"])}">{esc(explanation["title"])}</h2>')
        for clause in (c for c in result["clauses"] if c["id"] in explanation["clause_ids"]):
            links=''.join(f'<li><a href="#{esc(eid)}">{esc(eid)}</a> · {esc(evidence[eid]["statement"])}</li>' for eid in clause["evidence_ids"])
            flags='<p class="alert">'+esc(' '.join(clause["flags"]))+'</p>' if clause["flags"] else ''
            cards.append(f'<article class="clause {esc(clause["publication_status"])}" id="{esc(clause["id"])}"><div class="eyebrow">{esc(clause["id"])} · {esc(clause["kind"].replace("_"," "))}</div>'
                f'<div class="badge">{esc(clause["support_status"].replace("_"," "))} · {esc(clause["publication_status"])}</div><p class="proposition">{esc(clause["statement"])}</p>'
                f'<p><b>Reasoning:</b> {esc(clause["reasoning"])}</p><details><summary>Inspect cited evidence</summary><ul>{links}</ul></details>'
                f'<p><b>Alternative:</b> {esc(clause["alternative"])}</p><p><b>Challenge:</b> {esc(clause["challenge"])}</p>'
                f'<p class="muted"><b>Model self-check:</b> {esc(clause["model_assessment"]["reason"])}</p>{flags}'
                f'<p class="muted" id="judgment-{esc(clause["id"])}">Independent review pending.</p><button data-review-clause="{esc(clause["id"])}">Review this clause</button></article>')
    ledger=[]
    for item in result["evidence"]:
        buttons=''.join(f'<button data-picture="{esc(vid)}">Inspect {esc(vid)}</button> ' for vid in item["view_ids"])
        ledger.append(f'<details id="{esc(item["id"])}"><summary>{esc(item["id"])} · {esc(item["kind"].replace("_"," "))} · {esc(item["scale"])}</summary><p>{esc(item["statement"])}</p><p>{buttons}</p><p class="muted">{esc(item["status"])} · {esc("; ".join(item["limitations"]))}</p></details>')
    assessments={a["case_id"]:a for a in result["evidence_tests"]["assessments"]}
    tests=[]
    for clause in result["clauses"]:
        rows=''.join(f'<tr><td>{esc(p["condition"].replace("_"," "))}</td><td>{esc(assessments[p["case_id"]]["assessment"].replace("_"," "))}</td><td>{esc(assessments[p["case_id"]]["reason"])}</td></tr>' for p in result["evidence_tests"]["plan"] if p["clause_id"]==clause["id"])
        tests.append(f'<details><summary>{esc(clause["id"])} · paired evidence tests</summary><div class="table-wrap"><table><thead><tr><th>Condition</th><th>Raw model verdict</th><th>Reason</th></tr></thead><tbody>{rows}</tbody></table></div></details>')
    variants=[]
    for variant in result["visual_comparisons"]:
        rows=''.join(f'<tr><td>{esc(a["case_id"])}</td><td>{esc(a["assessment"].replace("_"," "))}</td><td>{esc(a["reason"])}</td></tr>' for a in variant["assessments"])
        variants.append(f'<details><summary>{esc(variant["id"].replace("_"," "))} · visible-support comparison</summary><button data-picture="{esc(variant["view_id"])}">Show this image</button><p class="muted">Mean L*: {variant["metrics"]["mean_L"]:.2f} · mean chroma: {variant["metrics"]["mean_chroma"]:.2f} · edge density: {variant["metrics"]["edge_density"]:.1%}</p><div class="table-wrap"><table><thead><tr><th>Clause</th><th>Raw model verdict</th><th>Reason</th></tr></thead><tbody>{rows}</tbody></table></div></details>')
    changes=''.join(f'<details><summary>{esc(d["claim_id"])} · description changed</summary><p><b>Earlier:</b> {esc(d["before"])}</p><p><b>Reinspected:</b> {esc(d["after"])}</p><p class="muted">{esc(d["assessment"])}</p></details>' for d in result["reanalysis"]["description_changes"])
    clause_changes=''.join(f'<details><summary>{esc(d["position"])} · new output at this position</summary><p><b>Earlier:</b> {esc(d["before"])}</p><p><b>New:</b> {esc(d["after"])}</p></details>' for d in result["reanalysis"]["clause_changes"] if d["before"]!=d["after"])
    bounded=result["reanalysis"].get("bounded_revision",{})
    if bounded.get("attempted"):clause_changes+='<details><summary>One bounded revision after reference/type checks</summary><pre>'+esc(json.dumps(bounded,indent=2,ensure_ascii=False))+'</pre></details>'
    data=json.dumps({"work_id":result["work_id"],"run_id":run_id,"result_sha256":sha(output/"reasoning.json"),
        "review_revision":result["binding"]["review_revision"],"base_sha256":result["binding"]["base_sha256"],
        "clauses":result["clauses"]},ensure_ascii=False).replace('<','\\u003c').replace('&','\\u0026')
    script=Path(__file__).with_name("reasoning_ui.js").read_text()
    title=original["artwork"]["title"] or result["work_id"]
    artist=original["artwork"]["artist"] or "Identity not supplied"
    clause_options=''.join(f'<option value="{esc(c["id"])}">{esc(c["id"])} · {esc(c["statement"][:100])}</option>' for c in result["clauses"])
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+esc(title)+''' · Evidence and reasoning</title><style>
:root{--ink:#17342e;--paper:#f5f2e9;--muted:#5d6b64;--line:#d7ded5;--accent:#a65c35}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui}main{max-width:1400px;padding:32px;margin:auto}h1{font:clamp(30px,4vw,46px)/1.15 Georgia,serif;margin:10px 0}h2{font:26px Georgia,serif}h3{font:20px Georgia,serif}a{color:var(--accent)}button{font:inherit;font-size:13px;border:1px solid #b8c8bc;background:#fffdf7;color:var(--ink);padding:8px 14px;border-radius:18px;cursor:pointer}button:disabled{opacity:.45;cursor:default}select,input,textarea{font:inherit;width:100%;padding:9px;border:1px solid #bdcbc0;background:#fffdf7;color:var(--ink);border-radius:4px}label{display:block;font-size:13px;margin:12px 0}.eyebrow{font-size:11px;letter-spacing:.12em;text-transform:uppercase;font-weight:700}.muted,small{color:var(--muted)}header{max-width:980px}.toolbar{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.layout{display:grid;grid-template-columns:minmax(320px,1.1fr) minmax(340px,1fr);gap:28px;align-items:start}.visual{position:sticky;top:16px}.picture{margin:12px 0;background:#e6e5dc;padding:12px;text-align:center}.picture img{max-width:100%;max-height:65vh;object-fit:contain}.picture figcaption{font-size:12px;color:var(--muted)}section,.clause{padding:22px;background:#fffdf7;border:1px solid var(--line);border-radius:6px;margin-bottom:18px}.proposition{font:21px/1.5 Georgia,serif}.clause.withheld{border-left:5px solid #a34b38}.clause.qualified{border-left:5px solid #bc8c36}.badge{display:inline-block;font-size:12px;padding:3px 8px;background:#e5eee6;border-radius:4px;margin-top:8px}.alert{color:#8e3c25;background:#f9e8dc;padding:10px}.job-state{padding:12px;background:#e5eee6;border-radius:4px;overflow-wrap:anywhere}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid var(--line)}.bottom{margin-top:30px}.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}[hidden]{display:none!important}@media(max-width:850px){main{padding:20px}.layout,.review-grid{grid-template-columns:1fr}.visual{position:static}.picture img{max-height:70vh}}
</style></head><body><main><header><div class="eyebrow">Painting analysis · version 0.4 · proposals await review</div><h1>'''+esc(title)+'''</h1><p>'''+esc(artist)+'''</p><p>Inspect how individual claims connect to whole-image, group and detail evidence. Each explanation has alternatives, challenges and controlled comparisons. Model self-checks remain separate from reviewer judgments.</p><div class="toolbar"><a href="#clause-review">Review clauses</a><a href="#review-panel">Correct source observations</a><a href="#experiments">Inspect comparisons</a><a href="/reasoning/index.html">Five-work gallery</a></div></header>
<section><div class="eyebrow">Correction-driven reanalysis</div><p id="reasoning-status" class="job-state" role="status">Connecting to the local review service…</p><button id="reasoning-rerun" disabled>Reinspect and regenerate from saved corrections</button> <button id="reasoning-cancel" disabled>Cancel queued/running analysis</button> <a id="reasoning-result-link" hidden>Open the new analysis</a><p class="muted">This run uses source-review revision '''+str(result["binding"]["review_revision"])+'''. Saving corrections does not silently replace it. A new run preserves the old output, uses fresh or cached inspections, and requires new review.</p></section>
<div class="layout"><aside class="visual"><label for="picture-select">Whole, group, detail or comparison view</label><select id="picture-select">'''+options+'''</select>'''+pictures+'''<p class="muted">Detail views use the source reproduction capped at 2048 pixels. They cannot establish pigment, binder, support, tool or artistic intention.</p><p><a href="reasoning.json">Evidence and tests JSON</a> · <a href="inference-audit.json">Native inference audit</a></p></aside><div>'''+''.join(cards)+'''</div></div>
<div class="bottom"><section id="clause-review"><div class="eyebrow">Attributed judgments · bound to this run</div><h2>Review an individual clause</h2><p id="clause-review-message" class="job-state" role="status">Connecting…</p><label>Clause<select id="clause-target">'''+clause_options+'''</select></label><label>Decision<select id="clause-decision"><option value="accepted">Accepted by this reviewer</option><option value="revised">Revised by this reviewer</option><option value="rejected">Rejected by this reviewer</option></select></label><label>Statement<textarea id="clause-statement" rows="3"></textarea></label><label>Reason or note<textarea id="clause-note" rows="2"></textarea></label><div class="review-grid"><label>Reviewer name<input id="clause-reviewer" maxlength="200"></label><label>Reviewer type<select id="clause-reviewer-type"><option value="human">Human</option><option value="assistant">Assistant</option><option value="automated_test">Automated test</option></select></label></div><button id="clause-save" disabled>Save clause judgment</button> <button id="clause-reset" disabled>Remove selected judgment</button> <button id="clause-export">Export clause judgments</button><p class="muted">Acceptance is an attributed decision, not a calibrated probability or proof of expertise. New model runs do not inherit acceptance. Corrected/rejected clauses flag their explanation for review.</p></section>
<section id="experiments"><h2>Does the model use the stated evidence?</h2><p>Each clause receives cited evidence with an uncited distractor, the cited evidence alone, removal of one cited item, and an empty-evidence condition. Case order is shuffled and condition names are withheld from the model. These are raw self-checks, not independent expert evaluation.</p><p>Empty-evidence violations in this run: <b>'''+str(len(result["evidence_tests"]["empty_evidence_violations"]))+'''</b>. An interpretation retaining support after one fact is removed can reflect redundancy; it is not automatically a failure.</p>'''+''.join(tests)+'''<p class="muted">'''+esc(result["evidence_tests"]["limits"])+'''</p><h3>Color and resolution comparisons</h3><p>Value-only RGB approximately preserves CIELAB lightness while removing chroma. Resolution is reduced to a longest side of 256 pixels. Each visual judgment receives only the proposition and displayed image, without original evidence text or transformation labels.</p>'''+''.join(variants)+'''</section>
<section><h2>Reinspection and revision trace</h2><p>'''+str(len(result["reanalysis"]["inspected_regions"]))+''' regions inspected; '''+str(result["reanalysis"]["cache_hits"])+''' inspection requests reused identical validated cache inputs. Text differences require review and are not accuracy improvements by themselves.</p>'''+changes+clause_changes+'''<p class="muted">'''+esc(result["reanalysis"]["comparison_limit"])+'''</p><details><summary>Reviewer feedback retained for this run</summary><pre>'''+esc(json.dumps(result["reanalysis"]["clause_feedback"],indent=2,ensure_ascii=False))+'''</pre></details></section>
'''+review_section(original,encoded(image))+'''<section><h2>Evidence ledger</h2>'''+''.join(ledger)+'''</section><section><h2>Open question and limits</h2><p>'''+esc(result["open_question"])+'''</p><ul>'''+''.join('<li>'+esc(x)+'</li>' for x in result["limits"])+'''</ul><details><summary>Run binding and model provenance</summary><pre>'''+esc(json.dumps({"binding":result["binding"],"model":result["model"]},indent=2))+'''</pre></details></section></div></main>
<script type="application/json" id="reasoning-data">'''+data+'''</script><script>'''+script+'''</script></body></html>'''
